tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const input = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const expected = new Map([
  ['AR', ['5', '3']],
  ['AV', ['-5', '-3']],
  ['AZ', ['9007199254740993', '4503599627370497']],
]);

function toDto(amount) {
  const dto = { unit: 'EUR-cent', value: amount.toString() };
  assert.equal(readMinor(dto.value), amount);
  return dto;
}

const rows = input.map(({ id, unitMinor, quantity }) => {
  assert(Number.isSafeInteger(quantity));
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, 'half-away');
  const feeIfDepartmentA = mulDivMinor(net, 1n, 2n, 'half-away');
  assert.deepEqual([net.toString(), feeIfDepartmentA.toString()], expected.get(id));
  return {
    id,
    status: 'fee_pending',
    net: toDto(net),
    feeIfDepartmentA: toDto(feeIfDepartmentA),
    decisionRequired: 'Марине нужно подтвердить, что строка относится к отделу А и к ней применяется R-31, или утвердить правило сбора для этой строки.',
  };
});

assert.equal(rows.length, expected.size);
assert.equal(new Set(rows.map(({ id }) => id)).size, expected.size);
const settlement = { releaseRule: 'R-31', rows };
writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
assert.deepEqual(JSON.parse(readFileSync('settlement.json', 'utf8')), settlement);
NODE
cat settlement.json"

